"""Read only resources of explicitly supplied own native PIDs; no global attribution."""
import pathlib,os,time,threading


def sample(pid):
    root=pathlib.Path('/proc')/str(pid)
    try:
        if root.stat().st_uid!=os.getuid():return {'pid':pid,'observed_monotonic_s':time.monotonic(),'process_unavailable':True,'reason':'PID ownership changed during exit or reuse; no resource content read'}
        stat=(root/'stat').read_text();parts=stat[stat.rfind(')')+2:].split()
        io={key:int(value)for key,value in(line.split(':',1)for line in(root/'io').read_text().splitlines())}
        rss=next(int(line.split()[1])*1024 for line in(root/'status').read_text().splitlines()if line.startswith('VmRSS:'))
        inodes=set();sockets=[];network_errors=[]
        try:
            for fd in(root/'fd').iterdir():
                try:
                    target=os.readlink(fd)
                    if target.startswith('socket:['):inodes.add(target[8:-1])
                except FileNotFoundError:pass
                except PermissionError as error:network_errors.append({'errno':error.errno,'path':str(fd),'reason':str(error)})
            for family in['tcp','tcp6']:
                for line in(root/'net'/family).read_text().splitlines()[1:]:
                    fields=line.split()
                    if len(fields)>9 and fields[9]in inodes:
                        tx,rx=fields[4].split(':')
                        sockets.append({'family':family,'owned_fd_inode':fields[9],'local_hex':fields[1],'peer_hex':fields[2],'state_hex':fields[3],'tx_queue_bytes':int(tx,16),'rx_queue_bytes':int(rx,16)})
        except(PermissionError,FileNotFoundError,ProcessLookupError)as error:network_errors.append({'errno':error.errno,'path':getattr(error,'filename',None),'reason':str(error)})
        return {'pid':pid,'process_start_ticks':int(parts[19]),'observed_monotonic_s':time.monotonic(),'cpu_ticks':int(parts[11])+int(parts[12]),'clock_ticks_per_second':os.sysconf('SC_CLK_TCK'),'rss_bytes':rss,'physical_read_bytes':io['read_bytes'],'physical_write_bytes':io['write_bytes'],'owned_tcp_sockets':sockets if not network_errors else None,'network_observation_errors':network_errors,'network_queue_scope':'only fd-inode matched own PID sockets; inaccessible observations are unknown, never zero/NIC attribution'}
    except(FileNotFoundError,ProcessLookupError,StopIteration):return {'pid':pid,'observed_monotonic_s':time.monotonic(),'process_unavailable':True}
    except PermissionError as error:return {'pid':pid,'observed_monotonic_s':time.monotonic(),'process_unavailable':True,'observation_error':{'errno':error.errno,'path':getattr(error,'filename',None),'reason':str(error)}}


class ResourceWindow:
    def __init__(self,nodes):self.nodes=nodes;self.stop=threading.Event();self.samples=[];self.errors=[]
    def capture(self):self.samples.append({'monotonic_s':time.monotonic(),'nodes':{label:sample(pid)for label,pid in list(self.nodes)}})
    def __enter__(self):
        self.capture()
        def collect():
            try:
                while not self.stop.is_set():
                    self.capture()
                    self.stop.wait(.1)
            except BaseException as error:self.errors.append(repr(error))
        self.thread=threading.Thread(target=collect);self.thread.start();return self
    def __exit__(self,*args):
        self.stop.set();self.thread.join(4)
        assert not self.thread.is_alive()and not self.errors,('native resource sampler',self.errors)
        self.capture()


def deltas(samples):
    groups={}
    for window in samples:
        for label,row in window['nodes'].items():
            if not row.get('process_unavailable'):groups.setdefault((label,row['pid'],row['process_start_ticks']),[]).append(row)
    result=[]
    for(label,pid,start_ticks),rows in groups.items():
        before,after=rows[0],rows[-1]
        if len(rows)<2:result.append({'label':label,'pid':pid,'process_start_ticks':start_ticks,'insufficient_samples':True,'sample_count':len(rows)});continue
        result.append({'label':label,'pid':pid,'process_start_ticks':start_ticks,'sample_count':len(rows),'wall_s':after['observed_monotonic_s']-before['observed_monotonic_s'],'cpu_seconds':(after['cpu_ticks']-before['cpu_ticks'])/before['clock_ticks_per_second'],'physical_read_bytes':after['physical_read_bytes']-before['physical_read_bytes'],'physical_write_bytes':after['physical_write_bytes']-before['physical_write_bytes'],'rss_start_bytes':before['rss_bytes'],'rss_end_bytes':after['rss_bytes']})
    return result

